var e=`https://www.rd.go.th/5937.html`,t={label:`ประมวลรัษฎากร มาตรา 38–64 — เว็บไซต์กรมสรรพากร`,url:e},n={"40(1)":`เงินได้เนื่องจากการจ้างแรงงาน`,"40(2)":`เงินได้เนื่องจากหน้าที่หรือตำแหน่งงานที่ทำหรือจากการรับทำงานให้`,"40(3)":`เงินปีหรือเงินได้มีลักษณะเป็นเงินรายปี`,"40(4)":`ดอกเบี้ยพันธบัตร ดอกเบี้ยเงินฝาก ดอกเบี้ยหุ้นกู้`,"40(5)":`เงินหรือประโยชน์อย่างอื่นที่ได้เนื่องจาก`,"40(6)":`เงินได้จากวิชาชีพอิสระ`,"40(7)":`เงินได้จากการรับเหมาที่ผู้รับเหมาต้องลงทุนด้วยการจัดหาสัมภาระ`,"40(8)":`เงินได้จากการธุรกิจ การพาณิชย์ การเกษตร`};function r(t){let r=n[t];return r?`${e}#:~:text=${encodeURIComponent(r)}`:e}var i={1:[{law:`มาตรา 56`,title:`หน้าที่ยื่นแบบและกำหนดเวลา`,summary:`ผู้มีเงินได้ต้องยื่นรายการเงินได้ของปีภาษีที่ผ่านมาภายในเดือนมีนาคมของปีถัดไป ผู้ที่โสดต้องยื่นเมื่อมีเงินได้เกิน 60,000 บาท (หรือมีเฉพาะเงินเดือนเกิน 120,000 บาท) ส่วนผู้มีคู่สมรสต้องยื่นเมื่อเงินได้เกิน 120,000 บาท (หรือมีเฉพาะเงินเดือนเกิน 220,000 บาท) การยื่นทางอินเทอร์เน็ตมักได้รับการขยายเวลาตามประกาศของกรมสรรพากรในแต่ละปี`},{law:`ภ.ง.ด.90 / ภ.ง.ด.91`,title:`เลือกแบบให้ถูกประเภท`,summary:`ภ.ง.ด.91 ใช้เมื่อมีเงินได้จากการจ้างแรงงานตามมาตรา 40(1) เพียงประเภทเดียว ถ้ามีเงินได้ประเภทอื่นด้วย เช่น ค่าจ้างฟรีแลนซ์ ค่าเช่า หรือเงินได้จากธุรกิจ ต้องใช้ ภ.ง.ด.90`},{law:`มาตรา 57 ตรี – 57 เบญจ`,title:`สามีภริยาเลือกยื่นรวมหรือแยกได้`,summary:`คู่สมรสที่จดทะเบียนสมรสเลือกได้ว่าจะยื่นแบบรวมกันหรือแยกกัน ถ้ายื่นรวม ให้ใช้เงินได้ของทั้งสองฝ่ายรวมเป็นฐานเดียวกัน ถ้าคู่สมรสไม่มีเงินได้ ผู้ยื่นหักค่าลดหย่อนคู่สมรสได้ 60,000 บาท`},{law:`มาตรา 35 และ 37`,title:`โทษเมื่อไม่ยื่นหรือยื่นข้อมูลเท็จ`,summary:`ไม่ยื่นแบบภายในกำหนดมีโทษปรับไม่เกิน 2,000 บาท ส่วนการเจตนายื่นข้อมูลเท็จหรือใช้อุบายเพื่อหลีกเลี่ยงภาษี มีโทษจำคุก 3 เดือนถึง 7 ปี และปรับ 2,000 ถึง 200,000 บาท`}],2:[{law:`มาตรา 39`,title:`เงินได้พึงประเมินคืออะไร`,summary:`ไม่ใช่แค่เงินสด แต่รวมถึงทรัพย์สินหรือประโยชน์อื่นที่คิดเป็นเงินได้ เช่น ค่าเช่าบ้านที่นายจ้างออกให้ หรือภาษีที่นายจ้างออกแทน`},{law:`มาตรา 40`,title:`เงินได้ 8 ประเภท`,summary:`40(1) เงินเดือนและค่าจ้าง · 40(2) ค่าจ้างงานที่รับทำเป็นครั้งคราว · 40(3) ค่าลิขสิทธิ์ · 40(4) ดอกเบี้ยและเงินปันผล · 40(5) ค่าเช่าทรัพย์สิน · 40(6) วิชาชีพอิสระ · 40(7) รับเหมาที่ต้องจัดหาสัมภาระเอง · 40(8) ธุรกิจ การพาณิชย์ และเงินได้อื่น ต้องกรอกให้ถูกประเภท เพราะแต่ละประเภทหักค่าใช้จ่ายได้ไม่เท่ากัน`},{law:`มาตรา 42`,title:`เงินได้ที่ได้รับยกเว้น`,summary:`เงินได้บางรายการไม่ต้องนำมารวมคำนวณภาษี เช่น เบี้ยเลี้ยงเดินทางที่จ่ายเพื่อการทำงานโดยเฉพาะ และดอกเบี้ยเงินฝากออมทรัพย์ที่ไม่เกินเกณฑ์ที่กฎหมายกำหนด`},{law:`มาตรา 42 ทวิ – 42 นว`,title:`การหักค่าใช้จ่าย`,summary:`เงินได้ตามมาตรา 40(1) และ 40(2) หักค่าใช้จ่ายได้ 50% แต่รวมกันไม่เกิน 100,000 บาท ส่วนเงินได้ประเภทอื่นหักแบบเหมาตามอัตราของแต่ละประเภท หรือหักตามจริงเมื่อมีหลักฐาน ระบบนี้คำนวณแบบหักเหมาให้`},{law:`มาตรา 50 และ 50 ทวิ`,title:`ภาษีหัก ณ ที่จ่าย`,summary:`ผู้จ่ายเงินได้ต้องหักภาษีไว้และออกหนังสือรับรองการหักภาษี (50 ทวิ) ให้ผู้รับเงิน ยอดที่ถูกหักไว้นำมาหักออกจากภาษีที่ต้องชำระตอนยื่นแบบได้ ถ้าถูกหักไว้เกินก็ขอคืนได้`},{law:`มาตรา 41`,title:`เงินได้จากต่างประเทศ`,summary:`ผู้อยู่ในประเทศไทยตั้งแต่ 180 วันในปีภาษีและมีเงินได้จากต่างประเทศ ต้องนำเงินได้นั้นมาเสียภาษีเมื่อนำเข้าประเทศไทย ตามคำสั่งกรมสรรพากรที่ ป.161/2566 และ ป.162/2566 ใช้กับเงินได้ที่เกิดตั้งแต่ 1 มกราคม 2567`}],3:[{law:`มาตรา 47`,title:`ค่าลดหย่อนส่วนตัวและครอบครัว`,summary:`ผู้มีเงินได้หักค่าลดหย่อนส่วนตัวได้ 60,000 บาท คู่สมรสที่ไม่มีเงินได้ 60,000 บาท บุตรคนละ 30,000 บาท (คนที่ 2 ขึ้นไปที่เกิดตั้งแต่ปี 2561 คนละ 60,000 บาท) ค่าฝากครรภ์ไม่เกิน 60,000 บาท และบิดามารดาอายุ 60 ปีขึ้นไปที่มีเงินได้ไม่เกิน 30,000 บาท คนละ 30,000 บาท`},{law:`มาตรา 47(7)`,title:`เงินบริจาค`,summary:`เงินบริจาคหักได้ไม่เกิน 10% ของเงินได้ที่เหลือหลังหักค่าใช้จ่ายและค่าลดหย่อนอื่นแล้ว การบริจาคเพื่อการศึกษา การกีฬา และโรงพยาบาลรัฐ หักได้ 2 เท่าของที่จ่ายจริง ตามพระราชกฤษฎีกาว่าด้วยการยกเว้นรัษฎากร แต่ต้องอยู่ในเพดาน 10% เช่นกัน`},{law:`กฎกระทรวง ฉบับที่ 126 (พ.ศ. 2509)`,title:`กองทุนและประกันที่ได้รับยกเว้นภาษี`,summary:`เงินที่จ่ายเข้ากองทุนสำรองเลี้ยงชีพ กองทุน RMF กองทุน SSF และเบี้ยประกันชีวิตแบบบำนาญ ได้รับยกเว้นภาษีตามเพดานรายการและเพดานสัดส่วนของเงินได้ และเมื่อรวมกลุ่มเพื่อการเกษียณต้องไม่เกิน 500,000 บาท ระบบตัดเพดานทุกชั้นให้อัตโนมัติ`},{law:`มาตรา 19`,title:`เก็บหลักฐานค่าลดหย่อนไว้เสมอ`,summary:`เจ้าพนักงานประเมินมีอำนาจออกหมายเรียกผู้ยื่นแบบมาตรวจสอบได้ภายใน 2 ปีนับแต่วันยื่น และขยายได้ถึง 5 ปีเมื่อมีหลักฐานว่าหลีกเลี่ยงภาษี จึงควรเก็บใบเสร็จ หนังสือรับรองกองทุน และใบอนุโมทนาบัตรไว้ให้ครบ`}],4:[{law:`มาตรา 48`,title:`อัตราภาษีขั้นบันได`,summary:`ภาษีคำนวณจากเงินได้สุทธิตามอัตราก้าวหน้า 0% ถึง 35% ผู้มีเงินได้ตามมาตรา 40(2) ถึง 40(8) รวมกันตั้งแต่ 120,000 บาทขึ้นไป ต้องคำนวณอีกวิธีคือ 0.5% ของเงินได้พึงประเมินเหล่านั้น แล้วเสียตามวิธีที่ได้ยอดสูงกว่า แต่ถ้าวิธี 0.5% ได้ไม่เกิน 5,000 บาทได้รับยกเว้น (ผลคือมีผลจริงเมื่อเงินได้เหล่านี้เกิน 1 ล้านบาท)`},{law:`มาตรา 27`,title:`เงินเพิ่มเมื่อชำระล่าช้า`,summary:`ชำระภาษีไม่ครบหรือไม่ทันกำหนด ต้องเสียเงินเพิ่มอีก 1.5% ต่อเดือนหรือเศษของเดือน แต่รวมแล้วไม่เกินจำนวนภาษีที่ต้องชำระ`},{law:`มาตรา 64`,title:`ผ่อนชำระได้ 3 งวด`,summary:`ถ้าภาษีที่ต้องชำระตั้งแต่ 3,000 บาทขึ้นไปและยื่นแบบภายในกำหนดเวลา ขอผ่อนชำระเป็น 3 งวดเท่า ๆ กันได้โดยไม่มีเงินเพิ่ม`},{law:`มาตรา 27 ตรี`,title:`สิทธิขอคืนภาษี`,summary:`ถ้าภาษีที่ถูกหัก ณ ที่จ่ายไว้มากกว่าภาษีที่ต้องเสีย ขอคืนส่วนที่เกินได้ ภายใน 3 ปีนับแต่วันสุดท้ายของกำหนดเวลายื่นแบบ`}]};export{r as i,e as n,t as r,i as t};